<br />using System;
<br />using System.Diagnostics;
<br />using StardewModdingAPI;
<br />using StardewModdingAPI.Events;
<br />using StardewValley;
<br />namespace StardewAffinity
<br />{
<br />    public sealed class ModEntry : Mod
<br />    {
<br />        private const string GmcmId = "spacechase0.GenericModConfigMenu";
<br />        private static readonly string[] ModeValues =
<br />        {
<br />            "ExcludeCpu0", // default
<br />            "AllCores",
<br />            "CustomMask"
<br />        };
<br />        private ModConfig Config = null!;
<br />        private bool? LastIsFocused;
<br />        private long? LastAppliedMask;
<br />        // Original affinity captured before we change anything.
<br />        private long? OriginalAffinityMask;
<br />        public override void Entry(IModHelper helper)
<br />        {
<br />            this.Config = helper.ReadConfig&lt;ModConfig&gt;();
<br />            helper.Events.GameLoop.GameLaunched += this.OnGameLaunched;
<br />            helper.Events.GameLoop.UpdateTicked += this.OnUpdateTicked;
<br />            // Best-effort initial apply (assume focused; Game1.game1 may be null this early).
<br />            this.TryCaptureOriginalAffinity();
<br />            this.TryApplyFocusedAffinity(force: true);
<br />        }
<br />        private void OnGameLaunched(object? sender, GameLaunchedEventArgs e)
<br />        {
<br />            this.RegisterGmcm();
<br />            this.TryCaptureOriginalAffinity();
<br />            this.TryApplyFocusedAffinity(force: true);
<br />        }
<br />        private void OnUpdateTicked(object? sender, UpdateTickedEventArgs e)
<br />        {
<br />            if (!this.Config.Enabled)
<br />                return;
<br />            if (!OperatingSystem.IsWindows())
<br />                return;
<br />            if (Game1.game1 is null)
<br />                return;
<br />            bool isFocused = Game1.game1.IsActive;
<br />            // only act when focus changes
<br />            if (this.LastIsFocused is null || this.LastIsFocused.Value != isFocused)
<br />            {
<br />                this.LastIsFocused = isFocused;
<br />                this.TryCaptureOriginalAffinity();
<br />                if (isFocused)
<br />                    this.TryApplyFocusedAffinity(force: false);
<br />                else
<br />                    this.TryRestoreOriginalAffinity(force: false);
<br />            }
<br />        }
<br />        private void TryCaptureOriginalAffinity()
<br />        {
<br />            if (this.OriginalAffinityMask.HasValue)
<br />                return;
<br />            if (!this.Config.Enabled)
<br />                return;
<br />            if (!OperatingSystem.IsWindows())
<br />                return;
<br />            try
<br />            {
<br />                var proc = Process.GetCurrentProcess();
<br />                // capture whatever the game is currently using before we modify it
<br />                this.OriginalAffinityMask = proc.ProcessorAffinity.ToInt64();
<br />                if (this.Config.LogInfo)
<br />                {
<br />                    this.Monitor.Log(
<br />                        this.Helper.Translation.Get("log.captured_original", new { mask = FormatMaskHex(this.OriginalAffinityMask.Value) }),
<br />                        LogLevel.Debug
<br />                    );
<br />                }
<br />            }
<br />            catch (Exception ex)
<br />            {
<br />                // Not fatal; we can fall back to "all cores" if needed.
<br />                if (this.Config.LogInfo)
<br />                {
<br />                    this.Monitor.Log(
<br />                        this.Helper.Translation.Get("log.capture_failed", new { error = ex.GetType().Name, message = ex.Message }),
<br />                        LogLevel.Debug
<br />                    );
<br />                }
<br />            }
<br />        }
<br />        private void TryApplyFocusedAffinity(bool force)
<br />        {
<br />            if (!this.Config.Enabled)
<br />                return;
<br />            if (!OperatingSystem.IsWindows())
<br />            {
<br />                if (this.Config.LogInfo)
<br />                    this.Monitor.Log(this.Helper.Translation.Get("log.not_windows"), LogLevel.Debug);
<br />                return;
<br />            }
<br />            int logicalCount = Environment.ProcessorCount;
<br />            int maxMaskBits = IntPtr.Size * 8; // 64 on 64-bit
<br />            int usableBits = Math.Min(logicalCount, maxMaskBits);
<br />            if (usableBits &lt;= 1)
<br />            {
<br />                if (this.Config.LogInfo)
<br />                    this.Monitor.Log(this.Helper.Translation.Get("log.not_enough_cores", new { cores = logicalCount }), LogLevel.Info);
<br />                return;
<br />            }
<br />            if (logicalCount &gt; usableBits &amp;&amp; this.Config.LogInfo)
<br />            {
<br />                this.Monitor.Log(
<br />                    this.Helper.Translation.Get("log.too_many_cores", new { cores = logicalCount, usable = usableBits }),
<br />                    LogLevel.Info
<br />                );
<br />            }
<br />            if (!TryGetDesiredMask(this.Config, usableBits, out long desiredMask, out string? errorKey))
<br />            {
<br />                this.Monitor.Log(this.Helper.Translation.Get(errorKey ?? "log.invalid_config"), LogLevel.Warn);
<br />                return;
<br />            }
<br />            // Avoid reapplying the same mask unless forced
<br />            if (!force &amp;&amp; this.LastAppliedMask.HasValue &amp;&amp; this.LastAppliedMask.Value == desiredMask)
<br />                return;
<br />            this.TrySetAffinityMask(
<br />                mask: desiredMask,
<br />                logKey: "log.applied_focused",
<br />                extraLogArgs: new { mode = this.Config.Mode, mask = FormatMaskHex(desiredMask), cores = logicalCount }
<br />            );
<br />        }
<br />        private void TryRestoreOriginalAffinity(bool force)
<br />        {
<br />            if (!this.Config.Enabled)
<br />                return;
<br />            if (!this.Config.RestoreOnUnfocus)
<br />                return;
<br />            if (!OperatingSystem.IsWindows())
<br />                return;
<br />            int logicalCount = Environment.ProcessorCount;
<br />            int maxMaskBits = IntPtr.Size * 8;
<br />            int usableBits = Math.Min(logicalCount, maxMaskBits);
<br />            long fallbackAll = MakeAllCoresMask(Math.Max(1, usableBits));
<br />            long restoreMask = this.OriginalAffinityMask ?? fallbackAll;
<br />            // Clamp to usable bits (avoid invalid bits)
<br />            restoreMask &amp;= fallbackAll;
<br />            if (restoreMask == 0)
<br />                restoreMask = fallbackAll;
<br />            // Avoid reapplying the same mask unless forced
<br />            if (!force &amp;&amp; this.LastAppliedMask.HasValue &amp;&amp; this.LastAppliedMask.Value == restoreMask)
<br />                return;
<br />            this.TrySetAffinityMask(
<br />                mask: restoreMask,
<br />                logKey: "log.restored_unfocused",
<br />                extraLogArgs: new { mask = FormatMaskHex(restoreMask) }
<br />            );
<br />        }
<br />        private void TrySetAffinityMask(long mask, string logKey, object extraLogArgs)
<br />        {
<br />            try
<br />            {
<br />                var proc = Process.GetCurrentProcess();
<br />                proc.ProcessorAffinity = new IntPtr(mask);
<br />                this.LastAppliedMask = mask;
<br />                if (this.Config.LogInfo)
<br />                    this.Monitor.Log(this.Helper.Translation.Get(logKey, extraLogArgs), LogLevel.Info);
<br />            }
<br />            catch (Exception ex)
<br />            {
<br />                this.Monitor.Log(
<br />                    this.Helper.Translation.Get("log.failed", new { error = ex.GetType().Name, message = ex.Message }),
<br />                    LogLevel.Warn
<br />                );
<br />            }
<br />        }
<br />        private static bool TryGetDesiredMask(ModConfig config, int usableBits, out long mask, out string? errorKey)
<br />        {
<br />            mask = 0;
<br />            errorKey = null;
<br />            long all = MakeAllCoresMask(usableBits);
<br />            string mode = (config.Mode ?? "").Trim();
<br />            if (mode.Equals("ExcludeCpu0", StringComparison.OrdinalIgnoreCase))
<br />            {
<br />                mask = all &amp; ~1L; // clear CPU 0
<br />                if (mask == 0)
<br />                {
<br />                    errorKey = "log.mask_zero";
<br />                    return false;
<br />                }
<br />                return true;
<br />            }
<br />            if (mode.Equals("AllCores", StringComparison.OrdinalIgnoreCase))
<br />            {
<br />                mask = all;
<br />                return true;
<br />            }
<br />            if (mode.Equals("CustomMask", StringComparison.OrdinalIgnoreCase))
<br />            {
<br />                if (!TryParseMask(config.CustomMask, out long parsed))
<br />                {
<br />                    errorKey = "log.custommask_parse_fail";
<br />                    return false;
<br />                }
<br />                // Clamp to usable bits
<br />                parsed &amp;= all;
<br />                if (parsed == 0)
<br />                {
<br />                    errorKey = "log.mask_zero";
<br />                    return false;
<br />                }
<br />                mask = parsed;
<br />                return true;
<br />            }
<br />            errorKey = "log.unknown_mode";
<br />            return false;
<br />        }
<br />        private static long MakeAllCoresMask(int usableBits)
<br />        {
<br />            if (usableBits &gt;= 64)
<br />                return -1L;
<br />            return (1L &lt;&lt; usableBits) - 1L;
<br />        }
<br />        private static bool TryParseMask(string? raw, out long value)
<br />        {
<br />            value = 0;
<br />            if (string.IsNullOrWhiteSpace(raw))
<br />                return false;
<br />            string s = raw.Trim();
<br />            try
<br />            {
<br />                if (s.StartsWith("0x", StringComparison.OrdinalIgnoreCase))
<br />                    value = Convert.ToInt64(s.Substring(2), 16);
<br />                else
<br />                    value = Convert.ToInt64(s, 10);
<br />                return value &gt; 0;
<br />            }
<br />            catch
<br />            {
<br />                return false;
<br />            }
<br />        }
<br />        private static string FormatMaskHex(long mask)
<br />            =&gt; "0x" + unchecked((ulong)mask).ToString("X");
<br />        private void RegisterGmcm()
<br />        {
<br />            var gmcm = this.Helper.ModRegistry.GetApi&lt;IGenericModConfigMenuApi&gt;(GmcmId);
<br />            if (gmcm is null)
<br />                return;
<br />            gmcm.Register(
<br />                mod: this.ModManifest,
<br />                reset: () =&gt; this.Config = new ModConfig(),
<br />                save: () =&gt;
<br />                {
<br />                    this.Helper.WriteConfig(this.Config);
<br />                    this.TryCaptureOriginalAffinity();
<br />                    this.TryApplyFocusedAffinity(force: true);
<br />                }
<br />            );
<br />            gmcm.AddSectionTitle(
<br />                mod: this.ModManifest,
<br />                text: () =&gt; this.Helper.Translation.Get("gmcm.section.title"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.section.tooltip")
<br />            );
<br />            gmcm.AddBoolOption(
<br />                mod: this.ModManifest,
<br />                getValue: () =&gt; this.Config.Enabled,
<br />                setValue: v =&gt; this.Config.Enabled = v,
<br />                name: () =&gt; this.Helper.Translation.Get("gmcm.enabled"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.enabled.tooltip")
<br />            );
<br />            gmcm.AddBoolOption(
<br />                mod: this.ModManifest,
<br />                getValue: () =&gt; this.Config.RestoreOnUnfocus,
<br />                setValue: v =&gt; this.Config.RestoreOnUnfocus = v,
<br />                name: () =&gt; this.Helper.Translation.Get("gmcm.restoreOnUnfocus"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.restoreOnUnfocus.tooltip")
<br />            );
<br />            gmcm.AddTextOption(
<br />                mod: this.ModManifest,
<br />                getValue: () =&gt; this.Config.Mode,
<br />                setValue: v =&gt; this.Config.Mode = v,
<br />                name: () =&gt; this.Helper.Translation.Get("gmcm.mode"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.mode.tooltip"),
<br />                allowedValues: ModeValues,
<br />                formatAllowedValue: v =&gt; this.Helper.Translation.Get($"gmcm.mode.{v}")
<br />            );
<br />            gmcm.AddTextOption(
<br />                mod: this.ModManifest,
<br />                getValue: () =&gt; this.Config.CustomMask,
<br />                setValue: v =&gt; this.Config.CustomMask = v,
<br />                name: () =&gt; this.Helper.Translation.Get("gmcm.custommask"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.custommask.tooltip"),
<br />                allowedValues: null,
<br />                formatAllowedValue: null
<br />            );
<br />            gmcm.AddBoolOption(
<br />                mod: this.ModManifest,
<br />                getValue: () =&gt; this.Config.LogInfo,
<br />                setValue: v =&gt; this.Config.LogInfo = v,
<br />                name: () =&gt; this.Helper.Translation.Get("gmcm.logInfo"),
<br />                tooltip: () =&gt; this.Helper.Translation.Get("gmcm.logInfo.tooltip")
<br />            );
<br />        }
<br />    }
<br />    // GMCM API (minimal/current signatures we use).
<br />    public interface IGenericModConfigMenuApi
<br />    {
